{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Brigatinib, which shares the 4-(piperazin-1-yl)anilino-pyrimidine motif with the query, has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Linezolid has essentially complete (100%) absolute oral bioavailability in humans, demonstrating that polar heteroaromatic drugs with amine-containing substituents can achieve high oral exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Encainide shows oral bioavailability of 20-30% in healthy subjects, at or above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Paliperidone extended-release has 28% absolute oral bioavailability in healthy volunteers, and its immediate-release form approaches 100%, supporting F ≥ 20% for this heteroaromatic ketone chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Ketanserin has absolute oral bioavailability of about 47-50% in healthy subjects, supporting high F for a moderately lipophilic heteroaromatic ketone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Rifapentine has 70% absolute oral bioavailability in healthy volunteers, showing that even large lipophilic molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20% (28-100%), with the most structurally similar compounds (brigatinib, paliperidone, ketanserin) in the 28-50% range; therefore the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present in the evidence set.",
    "Some records appear mismatched to their listed molecule SMILES (e.g., C32 reports tacrolimus while molecule 7 is a small-molecule CDK inhibitor; C43/C17 report GSK1322322 while molecule 1 is brigatinib), so those records were not weighted heavily.",
    "No record reports F below 20%; the lowest credible value is ~20-28%, so the threshold boundary is not directly challenged."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

